<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$canVerify=SchoolAuth::hasPermission('students.guardian.verify');$isGuardian=$role==='parent_guardian'&&SchoolAuth::hasPermission('portal.child');if(!$canVerify&&!$isGuardian){http_response_code(403);exit('Guardian relationship access is not permitted.');}$pdo=SchoolDatabase::connection();$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
 else try{$action=(string)($_POST['action']??'');
  if($action==='request'&&$isGuardian){$admission=strtoupper(trim((string)($_POST['admission_number']??'')));$relationship=trim((string)($_POST['relationship']??'Parent/Guardian'));if(!preg_match('/^[A-Z0-9][A-Z0-9-]{1,39}$/',$admission)||$relationship===''||mb_strlen($relationship)>60)throw new RuntimeException('Enter the student admission number and relationship.');$q=$pdo->prepare("SELECT id FROM students WHERE admission_number=:admission AND status='active'");$q->execute(['admission'=>$admission]);$studentId=(int)$q->fetchColumn();if($studentId){SchoolDatabase::transaction(function(PDO $pdo)use($user,$studentId,$relationship):void{$q=$pdo->prepare("INSERT INTO guardians (user_id,relationship_label) VALUES (:user,:relationship) ON DUPLICATE KEY UPDATE relationship_label=VALUES(relationship_label)");$q->execute(['user'=>(int)$user['id'],'relationship'=>$relationship]);$q=$pdo->prepare('SELECT id FROM guardians WHERE user_id=:user');$q->execute(['user'=>(int)$user['id']]);$guardianId=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT verification_status,ended_at FROM student_guardians WHERE student_id=:student AND guardian_id=:guardian FOR UPDATE');$q->execute(['student'=>$studentId,'guardian'=>$guardianId]);$existing=$q->fetch();if($existing&&!$existing['ended_at']&&$existing['verification_status']!=='rejected')throw new RuntimeException('A request or verified link already exists for that student.');if($existing){$q=$pdo->prepare("UPDATE student_guardians SET relationship=:relationship,verification_status='pending',verified_by=NULL,verified_at=NULL,ended_at=NULL WHERE student_id=:student AND guardian_id=:guardian");$q->execute(['relationship'=>$relationship,'student'=>$studentId,'guardian'=>$guardianId]);}else{$q=$pdo->prepare("INSERT INTO student_guardians (student_id,guardian_id,relationship,verification_status) VALUES (:student,:guardian,:relationship,'pending')");$q->execute(['student'=>$studentId,'guardian'=>$guardianId,'relationship'=>$relationship]);}(new AuditService())->record((int)$user['id'],'guardian.link.request','student_guardians',$studentId,['relationship'=>$relationship]);});}$message='Request received. If the admission number matches an active student, the school will review it.';
  }elseif(in_array($action,['verify','reject'],true)&&$canVerify){$studentId=(int)($_POST['student_id']??0);$guardianId=(int)($_POST['guardian_id']??0);SchoolDatabase::transaction(function(PDO $pdo)use($action,$studentId,$guardianId,$user):void{$q=$pdo->prepare("SELECT verification_status,ended_at FROM student_guardians WHERE student_id=:student AND guardian_id=:guardian FOR UPDATE");$q->execute(['student'=>$studentId,'guardian'=>$guardianId]);$link=$q->fetch();if(!$link||$link['verification_status']!=='pending'||$link['ended_at'])throw new RuntimeException('That guardian request is no longer pending.');$state=$action==='verify'?'verified':'rejected';$q=$pdo->prepare('UPDATE student_guardians SET verification_status=:status,verified_by=:actor,verified_at=UTC_TIMESTAMP() WHERE student_id=:student AND guardian_id=:guardian');$q->execute(['status'=>$state,'actor'=>(int)$user['id'],'student'=>$studentId,'guardian'=>$guardianId]);(new AuditService())->record((int)$user['id'],'guardian.link.'.$state,'student_guardians',$studentId,['guardian_id'=>$guardianId]);});$message='Guardian relationship '.($action==='verify'?'verified':'rejected').'.';
  }else{http_response_code(403);throw new RuntimeException('You cannot perform that guardian action.');}
 }catch(Throwable $exception){$error=$exception instanceof PDOException?'That guardian relationship conflicts with an existing record.':$exception->getMessage();}
}
if($canVerify){$q=$pdo->query("SELECT sg.student_id,sg.guardian_id,sg.relationship,sg.verification_status,sg.verified_at,s.admission_number,s.full_name student_name,u.full_name guardian_name,u.username FROM student_guardians sg JOIN students s ON s.id=sg.student_id JOIN guardians g ON g.id=sg.guardian_id JOIN users u ON u.id=g.user_id WHERE sg.ended_at IS NULL ORDER BY FIELD(sg.verification_status,'pending','verified','rejected'),s.full_name,u.full_name LIMIT 300");$links=$q->fetchAll();}else{$q=$pdo->prepare("SELECT sg.student_id,sg.relationship,sg.verification_status,sg.verified_at,s.admission_number,s.full_name student_name FROM student_guardians sg JOIN guardians g ON g.id=sg.guardian_id JOIN students s ON s.id=sg.student_id WHERE g.user_id=:user AND sg.ended_at IS NULL ORDER BY s.full_name");$q->execute(['user'=>(int)$user['id']]);$links=$q->fetchAll();}
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Guardian links';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-head"><div><h4>Guardian links</h4><p><?= $canVerify?'Review and verify parent or guardian relationships.':'Request a secure link to a student record using their admission number.' ?></p></div></div><?php if($message!==''): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if($error!==''): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<?php if($isGuardian): ?><div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-person-plus me-1"></i>Request a student link</span></div><div class="card-body"><form method="post" class="row g-2 align-items-end"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="request"><div class="col-md-6"><label class="form-label">Student admission number</label><input class="form-control" name="admission_number" maxlength="40" required></div><div class="col-md-4"><label class="form-label">Relationship</label><input class="form-control" name="relationship" maxlength="60" value="Parent/Guardian" required></div><div class="col-md-2"><button class="btn btn-primary w-100"><i class="bi bi-send me-1"></i>Request</button></div></form><p class="form-text mb-0 mt-2">A school administrator must verify the relationship before academic or financial records become visible.</p></div></div><?php endif; ?>
<div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-person-hearts me-1"></i><?= $canVerify?'Relationship register':'My relationship requests' ?></span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Student</th><?php if($canVerify): ?><th>Guardian</th><?php endif; ?><th>Relationship</th><th>Status</th><?php if($canVerify): ?><th>Action</th><?php endif; ?></tr></thead><tbody><?php foreach($links as $link): ?><tr><td><?= e($link['student_name']) ?><div class="small text-muted"><?= e($link['admission_number']) ?></div></td><?php if($canVerify): ?><td><?= e($link['guardian_name']) ?><div class="small text-muted"><?= e($link['username']??'') ?></div></td><?php endif; ?><td><?= e($link['relationship']) ?></td><td><span class="badge <?= $link['verification_status']==='verified'?'bg-success':($link['verification_status']==='pending'?'bg-warning text-dark':'bg-secondary') ?>"><?= e(ucfirst($link['verification_status'])) ?></span><?php if($link['verified_at']): ?><div class="small text-muted"><?= e(formatDate(substr($link['verified_at'],0,10))) ?></div><?php endif; ?></td><?php if($canVerify): ?><td><?php if($link['verification_status']==='pending'): ?><div class="d-flex gap-1"><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="verify"><input type="hidden" name="student_id" value="<?= (int)$link['student_id'] ?>"><input type="hidden" name="guardian_id" value="<?= (int)$link['guardian_id'] ?>"><button class="btn btn-sm btn-success">Verify</button></form><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="reject"><input type="hidden" name="student_id" value="<?= (int)$link['student_id'] ?>"><input type="hidden" name="guardian_id" value="<?= (int)$link['guardian_id'] ?>"><button class="btn btn-sm btn-outline-danger">Reject</button></form></div><?php else: ?>—<?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$links): ?><tr><td colspan="<?= $canVerify?5:3 ?>" class="text-center text-muted py-4">No guardian links or requests found.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
